import { getNotificationPreference, toggleNotifications } from './actions'

export default async function Home() {
  const isEnabled = await getNotificationPreference()

  return (
    <main style={{ padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Settings</h1>

      <div style={{ 
        border: '1px solid #ccc', 
        padding: '20px', 
        borderRadius: '8px',
        maxWidth: '400px'
      }}>
        <h2>Notifications</h2>
        <p>
          Current status: <strong>{isEnabled ? 'ON ✅' : 'OFF ❌'}</strong>
        </p>

        <form action={toggleNotifications}>
          <button 
            type="submit"
            style={{
              padding: '10px 20px',
              backgroundColor: isEnabled ? '#ef4444' : '#22c55e',
              color: 'white',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontSize: '16px'
            }}
          >
            {isEnabled ? 'Turn Off' : 'Turn On'}
          </button>
        </form>

        <p style={{ fontSize: '0.8rem', color: '#666', marginTop: '10px' }}>
          * Clicking this button invokes a Server Action that updates the state and calls <code>revalidatePath('/')</code> to refresh this page without a full reload.
        </p>
      </div>
    </main>
  );
}

